});

const lines = [];
rl.on("line", (line) => {
  lines.push(line);

  if (lines.length === 3) {
    const n = lines[0] - 0;
    const p = lines[1].split(" ").map(Number);
    const p_max = lines[2] - 0;

    console.log(getResult(n, p, p_max));
    lines.length = 0;
  }
