function getResult(n, p, p_max) {
  p = [0, ...p];

  // 01背包滚动数组优化解法
  const dp = new Array(p_max + 1).fill(0);

  for (let i = 1; i <= n; i++) {
    // 注意使用滚动数组优化时，关于背包承重的遍历应该倒序
    for (let j = p_max; j >= p[i]; j--) {
      dp[j] = Math.max(dp[j], dp[j - p[i]] + p[i]);
    }
  }

  return dp[p_max];
}

